async function activateAssetBoard(id){
    const board = assetBoardById(id);
    if(!board || ensureBoardNavigationState().hidden.includes(id)) return;
    const previousBoard = assetBoardById(activeTab);
    activeTab = id;
    registryRequestSeq += 1;
    registryPageLoading = false;
    resetBoardSelections();
    renderBoardNavigation();
    if(!board.system){
        const selectedSource = board.sourceBoard ? board.rootId : (boardSourceSelection[board.id] || '');
        applyRegistryFilterDefinition({category:board.category || '', rootId:selectedSource === '__automatic__' ? '' : selectedSource, groupSimilar:registryGroupSimilar});
        const queryKey = registryQueryString();
        const cached = registryAssetsQueryCache.get(queryKey);
        if(cached) applyRegistryAssetResponse(cached);
        else { registryAssets = []; registryTotal = null; registryTotalKnown = false; }
        registryLoading = !cached;
        render();
        loadCustomBoardFolderDirectories(board).catch(() => null);
        if(!cached){
            refreshRegistryAssets(false).then(() => { if(activeTab === id) render(); }).catch(err => setStatus(err.message || '绱犳潗搴撳姞杞藉け璐?'));
        }
        return;
    }
    if(board.id === 'registry' && previousBoard?.system === false){
        applyRegistryFilterDefinition({groupSimilar:registryGroupSimilar});
        const queryKey = registryQueryString();
        const cached = registryAssetsQueryCache.get(queryKey);
        if(cached) applyRegistryAssetResponse(cached);
        registryLoading = false;
        render();
        if(!cached) refreshRegistryAssets(false).then(() => { if(activeTab === id) render(); }).catch(err => setStatus(err.message || '绱犳潗搴撳姞杞藉け璐?'));
        return;
    }
    render();
}
function reorderAssetBoard(sourceId, targetId){
    if(!sourceId || sourceId === 'registry' || !targetId || sourceId === targetId) return false;
    const state = ensureBoardNavigationState();
    const order = state.order.filter(id => id !== sourceId);
    const targetIndex = order.indexOf(targetId);
    if(targetIndex < 0) return false;
    order.splice(Math.max(1, targetIndex), 0, sourceId);
    state.order = ['registry', ...order.filter(id => id !== 'registry')];
    saveBoardNavigationState();
    return true;
}
function moveAssetBoardByKeyboard(id, direction){
    if(id === 'registry') return;
    const visible = visibleAssetBoards().map(item => item.id);
    const index = visible.indexOf(id);
    const target = visible[index + direction];
    if(index < 0 || !target || target === 'registry') return;
    const state = ensureBoardNavigationState();
    const sourceIndex = state.order.indexOf(id);
    const targetIndex = state.order.indexOf(target);
    if(sourceIndex < 1 || targetIndex < 1) return;
    [state.order[sourceIndex], state.order[targetIndex]] = [state.order[targetIndex], state.order[sourceIndex]];
    saveBoardNavigationState();
    renderBoardNavigation();
    requestAnimationFrame(() => assetTabsEl?.querySelector(`[data-tab="${CSS.escape(id)}"]`)?.focus());
}
function setAssetBoardHidden(id, hidden){
    if(id === 'registry') return;
    const state = ensureBoardNavigationState();
    const values = new Set(state.hidden);
    if(hidden) values.add(id); else values.delete(id);
    state.hidden = [...values];
    if(activeTab === id && hidden) activeTab = 'registry';
    saveBoardNavigationState();
    renderBoardNavigation();
    render();
}
async function removeAssetSourceRegistrations(sourceIds=[]){
    const ids = new Set((Array.isArray(sourceIds) ? sourceIds : [...sourceIds]).map(String).filter(Boolean));
    if(!ids.size) return null;
    const state = ensureBoardNavigationState();
    const referenced = new Set(state.customBoards.flatMap(item => (item.sources || []).map(source => String(source.id || ''))));
    const removableIds = new Set([...ids].filter(sourceId => !referenced.has(sourceId)));
    if(!removableIds.size) return null;
    const entries = storageExtraLocalEntries().filter(entry => !removableIds.has(String(entry.id || '')));
    const names = storageLocalLibraryNames();
    removableIds.forEach(sourceId => delete names[sourceId]);
    const data = await apiJsonResponse(assetManagerApi.updateStorageSettings({
        dirs:storageSettingsState.dirs || {},
        extra_local_entries:entries,
        local_library_names:names,
        local_library_order:localLibraries.map(lib => lib.id).filter(id => !removableIds.has(String(id))),
    }));
    applyStorageSettingsData(data || {});
    registryAssets = registryAssets.filter(item => !removableIds.has(String(item.storage_root_id || '')));
    registryFacets.roots = (registryFacets.roots || []).filter(root => !removableIds.has(String(root.id || '')));
    if(registryStatus?.overview?.roots){
        registryStatus.overview.roots = registryStatus.overview.roots.filter(root => !removableIds.has(String(root.id || '')));
    }
    registryAssetsQueryCache.clear();
    return removableIds;
}
async function deleteCustomAssetBoard(id){
    const state = ensureBoardNavigationState();
    const board = state.customBoards.find(item => item.id === id);
    if(!board || !window.confirm(`删除资源库“${board.name}”？仅移除该资源库看板定义，不会注销其素材来源路径；如需停止索引并注销路径，请在来源设置中单独移除来源。`)) return;
    state.customBoards = state.customBoards.filter(item => item.id !== id);
    state.order = state.order.filter(value => value !== id);
    state.hidden = state.hidden.filter(value => value !== id);
    if(activeTab === id) activeTab = 'registry';
    saveBoardNavigationState();
    // 【修复问题5】删除看板与注销素材来源解耦：删除只移除看板定义，已登记路径保留。
    // 保留的路径会以“已登记素材库”自动看板继续显示；注销路径请在来源设置中显式操作。
    renderBoardNavigation();
    renderStorageSettingsModal();
    render();
    setStatus(`已删除资源库“${board.name}”，素材来源路径已保留，可在来源设置中单独注销`);
}
async function removeGeneratedSourceBoard(rootId, name='素材库'){
    const sourceId = String(rootId || '').trim();
    if(!sourceId || !sourceId.startsWith('local')) return;
    if(!window.confirm(`移除素材库”${name}”？将停止该路径的索引并从资产中心隐藏其内容，不会删除源文件。`)) return;
    setStatus(`正在移除素材库“${name}”…`);
    try {
        const removed = await removeAssetSourceRegistrations([sourceId]);
        if(!removed?.size) throw new Error('素材来源未移除，请刷新后重试');
        if(activeTab === `source_library_${sourceId}`) activeTab = 'registry';
        renderBoardNavigation();
        renderStorageSettingsModal();
        render();
        setStatus(`已移除素材库”${name}”，索引任务已停止`);
    } catch(err){
        setStatus(err.message || '素材库路径移除失败');
    }
}
function renderAssetBoardSettingsBody(){
    const hidden = new Set(ensureBoardNavigationState().hidden);
    return `<section class="asset-pref-section board-settings-section">
        <div class="asset-pref-title"><i data-lucide="panel-top"></i><span>看板显示</span><small>${allAssetBoards().length} 个看板</small></div>
        <div class="board-settings-list">${allAssetBoards().map(board => {
            const visible = board.id === 'registry' || !hidden.has(board.id);
            const editable = !board.system && !board.sourceBoard;
            return `<div class="board-settings-row ${board.fixed ? 'fixed' : ''}">
                <span class="board-settings-icon"><i data-lucide="${escapeAttr(board.icon)}"></i></span>
                ${editable
                    ? `<button class="board-settings-copy board-settings-edit" type="button" data-board-edit="${escapeAttr(board.id)}" title="修改资源库名称和路径"><strong>${escapeHtml(board.name)}</strong><small>点击修改名称和路径</small></button>`
                    : `<span class="board-settings-copy"><strong>${escapeHtml(board.name)}</strong><small>${board.fixed ? '固定首位' : board.system ? '系统看板' : '已登记素材库'}</small></span>`}
                <button class="board-visibility-control" type="button" role="switch" aria-checked="${visible}" aria-label="${visible ? '隐藏' : '显示'} ${escapeAttr(board.name)}" title="${visible ? '隐藏' : '显示'} ${escapeAttr(board.name)}" data-board-visibility="${escapeAttr(board.id)}" ${board.fixed ? 'disabled' : ''}><span class="registry-feature-switch ${visible ? 'is-on' : ''}"><i></i></span><em>${visible ? '显示' : '隐藏'}</em></button>
                ${board.system ? '' : board.sourceBoard
                    ? (String(board.rootId || '').startsWith('local')
                        ? `<button class="board-settings-delete" type="button" data-source-board-delete="${escapeAttr(board.rootId || '')}" data-source-board-name="${escapeAttr(board.name)}" aria-label="移除 ${escapeAttr(board.name)}" title="移除素材路径并停止索引"><i data-lucide="trash-2"></i></button>`
                        : '')
                    : `<button class="board-settings-delete" type="button" data-board-delete="${escapeAttr(board.id)}" aria-label="删除 ${escapeAttr(board.name)}"><i data-lucide="trash-2"></i></button>`}
            </div>`;
        }).join('')}</div>
    </section>`;
}
function renderAssetAiSettingsBody(){
    const providers = localCaptionProviders();
    if(!assetAiSettingsState.loading) normalizeLocalCaptionSettings();
    const provider = providers.find(item => item.id === localCaptionProvider) || providers[0];
    const models = (provider?.chat_models || []).filter(Boolean);
    const stateLabel = assetAiSettingsState.loading ? '正在读取…' : assetAiSettingsState.saving ? '正在保存…' : assetAiSettingsState.message || (providers.length ? '已连接可用模型' : '请先配置 API 平台');
    return `<section class="asset-pref-section board-ai-settings" data-board-ai-settings>
        <div class="asset-pref-title"><i data-lucide="sparkles"></i><span>AI 分类设置</span><small>${escapeHtml(stateLabel)}</small></div>
        <div class="board-ai-settings-grid">
            <label class="storage-dir-row board-ai-compact"><span>平台</span><select id="prefCaptionProvider" ${providers.length ? '' : 'disabled'}>${providers.length ? providers.map(provider => `<option value="${escapeAttr(provider.id)}" ${provider.id === localCaptionProvider ? 'selected' : ''}>${escapeHtml(provider.name || provider.id)}</option>`).join('') : '<option value="">暂无视觉平台</option>'}</select></label>
            <label class="storage-dir-row board-ai-compact"><span>模型</span><select id="prefCaptionModel" ${models.length ? '' : 'disabled'}>${models.length ? models.map(model => `<option value="${escapeAttr(model)}" ${model === localCaptionModel ? 'selected' : ''}>${escapeHtml(model)}</option>`).join('') : '<option value="">暂无可用模型</option>'}</select></label>
            <label class="storage-dir-row board-ai-compact"><span>反推提示词</span><input id="prefCaptionPrompt" value="${escapeAttr(localCaptionPrompt || '描述图片')}" placeholder="描述图片"></label>
            <button class="board-ai-auto-control" type="button" role="switch" aria-checked="${localAutoClassify}" data-board-ai-auto ${assetAiSettingsState.saving ? 'disabled' : ''}><span class="registry-feature-switch ${localAutoClassify ? 'is-on' : ''}"><i></i></span><span><strong>一键 AI 智能分类</strong><small>打开立即执行，关闭立即停止</small></span></button>
            <label class="storage-dir-row board-ai-extra"><span>智能分类追加要求</span><input id="prefClassifyPrompt" value="${escapeAttr(localClassifyPrompt || '')}" placeholder="例如：镜头焦段、商业用途、产品材质"></label>
            <details class="board-ai-rule"><summary><span>智能分类规则</span><small>展开编辑 JSON 输出规则</small></summary><textarea id="prefClassificationRule" class="asset-pref-rule-textarea" rows="5" placeholder="智能分类规则">${escapeHtml(assetAiSettingsState.rule || assetAiSettingsState.defaultRule || '')}</textarea></details>
        </div>
        <div class="storage-settings-actions inline board-ai-actions">
            <button class="asset-btn" type="button" data-board-ai-reset ${assetAiSettingsState.loading || assetAiSettingsState.saving ? 'disabled' : ''}><i data-lucide="rotate-ccw"></i><span>恢复内置规则</span></button>
            <button class="asset-btn primary" type="button" data-board-ai-save ${assetAiSettingsState.loading || assetAiSettingsState.saving ? 'disabled' : ''}><i data-lucide="save"></i><span>保存 AI 分类设置</span></button>
        </div>
    </section>`;
}
function renderRegistryFeatureControl(feature){
    const iconName = feature.id === 'thumbnail' ? 'image' : feature.id === 'video_storyboard' ? 'grid-3x3' : feature.id === 'metadata' ? 'file-scan' : feature.id === 'fulltext' ? 'text-search' : feature.id === 'font' ? 'type' : feature.id === 'model' ? 'box' : 'refresh-cw';
    return `<button class="board-feature-control" type="button" role="switch" aria-checked="${Boolean(feature.enabled)}" data-registry-feature-toggle="${escapeAttr(feature.id || '')}" ${registryFeatureBusyId === feature.id ? 'disabled' : ''}><span class="registry-feature-switch ${feature.enabled ? 'is-on' : ''}"><i></i></span><span class="registry-feature-label"><i data-lucide="${iconName}"></i>${escapeHtml(feature.name || '')}</span></button>`;
}
